import{z as t,x as i,o as e,c as p,q as s,j as o,D as a,d as A,s as n,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"微基准与真实负载","description":"","frontmatter":{"title":"微基准与真实负载","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-microbench-vs-real.md","filePath":"cs/pe3-microbench-vs-real.md","lastUpdated":1791413859000}'),d={name:"cs/pe3-microbench-vs-real.md"};function m(D,E,f,C,h,c){const r=i("Mermaid");return e(),p("div",null,[E[2]||(E[2]=s('<h1 id="微基准与真实负载" tabindex="-1">微基准与真实负载 <a class="header-anchor" href="#微基准与真实负载" aria-label="Permalink to &quot;微基准与真实负载&quot;">​</a></h1><div class="epigraph"><p>微基准回答「这块代码的墙有多高」，真实负载回答「这堵墙挡住了谁」；两问不同，把前一个答案当成后一个，是最便宜的自我欺骗。</p><footer>—— 据 Amdahl, AFIPS 1967 与 Gregg, Systems Performance, 2nd ed., 2018 的口径整理</footer></div><p><a href="/cs/pe3-benchmark-pitfalls">上一课</a>把自建基准的四环控制钉了下来：平台、状态、负载、统计，缺一失守。但即便四环全对，你拿到的仍只是<strong>那个被测单元</strong>在<strong>那个负载</strong>下的数字。本课处理这类数字最常见的误用：微基准跑赢了十倍，上线纹丝不动。微基准——对单个函数、数据结构或内核的隔离计时——是性能工程里生产率最高的工具，也是被误读最多的工具；本课给它划清与真实负载的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「微基准赢了、线上没变」有两个独立来源。其一，收益上限由占比决定：目标组件只占端到端时间的 \\(f\\)，无论它加速多少倍，整体收益都封在 Amdahl 的账上——占比百分之五的组件优化一百倍，整体也只快百分之五。其二，微基准剥离了调用上下文：真实调用点上的数据分布、工作集大小、缓存与分支预测器状态、以及共享同一台机器的邻居，全都不在微基准的计时区间里。不这么做会错在哪：把一个季度的优化预算投给哈希表，理由是隔离计时快了两倍——而生产里这张表的命中率早就把它的耗时挤出了关键路径。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步先归因，后动手。用<a href="/cs/obs-perf-deep">perf 的深化</a>与<a href="/cs/obs-flamegraphs">火焰图</a>在真实负载上确认目标组件的占比，再用 Amdahl 上限决定值不值得：组件占比 \\(f\\)、可加速 \\(k\\) 倍时，整体加速比 \\(S=\\dfrac{1}{(1-f)+f/k}\\)。上限低于验收门限，微基准根本不必写——这一步止损的钱比后面所有优化都多。</p><p>第二步，微基准要复现调用点的上下文，而不是「干净」的输入：键长与取值分布照抄生产抽样；工作集分档测——同一张表在 L1、L2、DRAM 三档工作集下是三个性能；调用形态分热循环与冷调用，前者吃分支预测器的福利，后者付缓存冷启动的税。上一课的预热与锁频纪律原样适用。</p><p><span class="marginnote">数字实例（工作集分档差多少）：一张 16 字节每条目的哈希表，条目全在 32 KB 的 L1 里时查询约几纳秒；涨到 4 MB 进 L2 变十几纳秒；涨到 2 GB 只能去 DRAM，就是上百纳秒——同一段代码，工作集差 6 万倍，耗时也差几十倍。「表多快」从来不是单个数，是随工作集变的一族数。</span></p><p>第三步，分工收账：微基准负责<strong>选方案</strong>，端到端负责<strong>收账</strong>。任何微基准的胜者都要回到上一课搭的端到端基准里跑一遍真实负载模型，整体指标不动，方案就不算赢。</p>',10)),(e(),o(l,null,{default:a(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REAL%5B%22%E7%9C%9F%E5%AE%9E%E8%B4%9F%E8%BD%BD%E7%94%BB%E5%83%8F%EF%BC%9A%E7%81%AB%E7%84%B0%E5%9B%BE%E5%AE%9A%E4%BD%8D%E5%8D%A0%E6%AF%94%22%5D%20--%3E%20AMD%5B%22Amdahl%20%E4%B8%8A%E9%99%90%EF%BC%9A%E5%80%BC%E4%B8%8D%E5%80%BC%E5%BE%97%22%5D%0A%20%20AMD%20--%3E%7C%22%E4%B8%8A%E9%99%90%E4%B8%8D%E8%B6%B3%EF%BC%8C%E5%81%9C%E6%89%8B%22%7C%20STOP%5B%22%E6%AD%A2%E6%8D%9F%EF%BC%9A%E6%8D%A2%E7%9B%AE%E6%A0%87%22%5D%0A%20%20AMD%20--%3E%7C%22%E5%80%BC%E5%BE%97%22%7C%20MB%5B%22%E5%BE%AE%E5%9F%BA%E5%87%86%EF%BC%9A%E5%A4%8D%E7%8E%B0%E8%B0%83%E7%94%A8%E7%82%B9%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20MB%20--%3E%20E2E%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E5%9F%BA%E5%87%86%E6%94%B6%E8%B4%A6%22%5D%0A%20%20E2E%20--%3E%7C%22%E6%95%B4%E4%BD%93%E6%8C%87%E6%A0%87%E4%B8%8D%E5%8A%A8%22%7C%20BACK%5B%22%E5%9B%9E%E7%9C%9F%E5%AE%9E%E8%B4%9F%E8%BD%BD%E9%87%8D%E6%96%B0%E5%BD%92%E5%9B%A0%22%5D%0A%20%20E2E%20--%3E%7C%22%E8%BE%BE%E6%A0%87%22%7C%20SHIP%5B%22%E4%BA%A4%E4%BB%98%EF%BC%9A%E8%AE%B0%E5%BD%95%E5%88%A4%E6%8D%AE%E4%B8%8E%E7%8E%AF%E5%A2%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"Amdahl 上限为什么是硬的：分母里的 \\((1-f)\\) 是你没动的部分，\\(k\\) 再大也只是把 \\(f/k\\) 压向零，\\(S\\) 封顶在 \\(1/(1-f)\\)。微基准为什么系统性高估收益：隔离消除了共享资源上的争用——容量、内存带宽、TLB——而真实调用点上你的「优化」可能正是别人的瓶颈来源；隔离计时测出的是理想条件下的墙，不是走廊里的墙。端到端为什么是唯一收账口径：用户等待只有一条时间线，组件墙再高，不在关键路径上就不产生体验。",-1)),E[5]||(E[5]=B("p",null,[B("span",{class:"marginnote"},"一个常被跳过的算术：组件占端到端 30%、微基准加速 10 倍，整体上限 \\(1/(0.7+0.03)\\approx 1.37\\)——天花板是 37%，汇报里却常写成「10 倍优化」。占比 \\(f\\) 与倍数 \\(k\\) 必须一起报，缺一个数字就是半张收据。")],-1)),(e(),o(l,null,{default:a(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20MICRO%5B%22%E5%BE%AE%E5%9F%BA%E5%87%86%EF%BC%88%E9%9A%94%E7%A6%BB%E8%AE%A1%E6%97%B6%EF%BC%89%22%5D%0A%20%20%20%20M1%5B%22%E5%8F%AA%E6%9C%89%E7%9B%AE%E6%A0%87%E7%BB%84%E4%BB%B6%22%5D%20--%3E%20M2%5B%22%E6%97%A0%E9%82%BB%E5%B1%85%E3%80%81%E6%97%A0%E4%BA%89%E7%94%A8%22%5D%0A%20%20%20%20M2%20--%3E%20M3%5B%22%E6%B5%8B%E5%87%BA%EF%BC%9A%E7%90%86%E6%83%B3%E5%A2%99%E9%AB%98%22%5D%0A%20%20end%0A%20%20subgraph%20PROD%5B%22%E7%9C%9F%E5%AE%9E%E8%B0%83%E7%94%A8%E7%82%B9%22%5D%0A%20%20%20%20P1%5B%22%E7%BB%84%E4%BB%B6%E5%9C%A8%E9%93%BE%E8%B7%AF%E4%B8%AD%E9%97%B4%22%5D%20--%3E%20P2%5B%22%E5%85%B1%E4%BA%AB%E7%BC%93%E5%AD%98%E3%80%81%E5%B8%A6%E5%AE%BD%E3%80%81TLB%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%22%E6%B5%8B%E5%87%BA%EF%BC%9A%E5%90%AB%E6%8E%92%E9%98%9F%E4%B8%8E%E5%B9%B2%E6%89%B0%E7%9A%84%E7%9C%9F%E5%AE%9E%E8%80%97%E6%97%B6%22%5D%0A%20%20end%0A%20%20MICRO%20--%3E%7C%22%E5%B0%91%E7%AE%97%E4%BA%86%E4%BB%80%E4%B9%88%22%7C%20GAP%5B%22%E5%B7%AE%E8%B7%9D%EF%BC%9A%E7%B3%BB%E7%BB%9F%E6%80%A7%E9%AB%98%E4%BC%B0%EF%BC%8C%E6%98%AF%E5%81%8F%E5%B7%AE%E4%B8%8D%E6%98%AF%E5%99%AA%E5%A3%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p>这张图回答的问题是：微基准到底把哪些东西「关在了门外」？左边是它给你看的理想世界——组件独占一切资源；右边是真实世界——组件和邻居共享缓存与内存带宽，请求在链路上排队。两边数字的差不是随机误差，而是固定方向的系统性偏差：微基准永远往好里高估，所以端到端才有「收账」的资格。</p><p><span class="marginnote">直觉类比：微基准像在空跑道上测百米成绩，真实负载是早高峰挤满人的马路——同样的腿，跑出的完全是两个数。空跑道成绩用来挑运动员（选方案）没问题，但预测送外卖要几分钟（收账），必须去真实马路上量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>微基准不是可疑的仪式：库作者与内核作者只有它——调用方千差万别，他们必须为每个工作集分档交付墙高。它的边界是回答<strong>结构</strong>问题（这个结构在给定分布与工作集下多快），不回答<strong>交付</strong>问题（用户快了多少）。GPU 侧有同款纪律：<a href="/cs/gpu-profiling">性能计数与 profiling</a> 里 NCU 的微秒不能当线上延迟，单 kernel 深潜与系统时间线是两种采集。并行的收益另有<a href="/cs/work-span-model">work-span 与 fork-join</a> 的跨度封顶，那是 Amdahl 在算法侧的表亲。主干课的<a href="/cs/par-roofline-map">roofline 的深化与收束</a>讲墙从机器上来，本课讲墙在交付里算账。</p><p><span class="marginnote">常见误区：以为「微基准快了 10 倍」至少说明优化没白做，上线只是收益打折。实际上可能一分收益都没有——如果该组件早已不在关键路径上，或它的缓存占用减少反而喂饱了旁边的热点，端到端甚至可能变慢。收益是否存在，只能由端到端收账说了算。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>微基准选方案、端到端收账，两步不可互相替代、也不可只做一步。</li><li>先归因再动手：占比乘倍数过 Amdahl 上限，天花板不够就止损。</li><li>微基准要复现调用点上下文：输入分布、工作集分档、调用形态，缺了就测着另一个系统。</li><li>隔离消除共享资源争用，所以微基准系统性高估收益；这是偏差不是噪声。</li><li>出处：Amdahl, <em>AFIPS Conference Proceedings</em>, 1967；Gregg, <em>Systems Performance</em>, 2nd ed., 2018；据本课三步分工口径整理。</li></ul>',7))])}const u=t(d,[["render",m]]);export{g as __pageData,u as default};
